/** urn:corpus:inventory:reservation:error:reservation_not_found — No reservation has this identifier */
export const ReservationReservationNotFoundSchema = v.object({
  kind: v.literal("urn:corpus:inventory:reservation:error:reservation_not_found"),
  reservation_id: ReservationReservationIdSchema,
});
export type ReservationReservationNotFound = v.InferOutput<typeof ReservationReservationNotFoundSchema>;
export type ReservationReservationNotFoundInput = v.InferInput<typeof ReservationReservationNotFoundSchema>;

/** urn:corpus:inventory:stock:error:insufficient_stock — The stock cannot cover the request, so nothing changed */
export const StockInsufficientStockSchema = v.object({
  kind: v.literal("urn:corpus:inventory:stock:error:insufficient_stock"),
  short_lines: v.pipe(v.array(StockShortLineSchema), v.minLength(1)),
});
export type StockInsufficientStock = v.InferOutput<typeof StockInsufficientStockSchema>;
export type StockInsufficientStockInput = v.InferInput<typeof StockInsufficientStockSchema>;

/** urn:corpus:inventory:stock:error:unknown_location — The service does not know the location */
export const StockUnknownLocationSchema = v.object({
  kind: v.literal("urn:corpus:inventory:stock:error:unknown_location"),
  location: StockLocationSchema,
});
export type StockUnknownLocation = v.InferOutput<typeof StockUnknownLocationSchema>;
export type StockUnknownLocationInput = v.InferInput<typeof StockUnknownLocationSchema>;

/** urn:corpus:inventory:stock:error:unknown_sku — The service does not know the SKU */
export const StockUnknownSkuSchema = v.object({
  kind: v.literal("urn:corpus:inventory:stock:error:unknown_sku"),
  sku: StockSkuSchema,
});
export type StockUnknownSku = v.InferOutput<typeof StockUnknownSkuSchema>;
export type StockUnknownSkuInput = v.InferInput<typeof StockUnknownSkuSchema>;

// Conditions

/** urn:corpus:inventory:adjustment:operation:adjust_stock — when: output.available = 0 */
export const AdjustmentAdjustStockWhen2 = (p: { input: AdjustmentAdjustment; output: StockStockLevel }): boolean =>
  (p.output.available as number) === 0;

/** urn:corpus:inventory:adjustment:operation:adjust_stock — caller: caller.role = 'warehouse_supervisor' */
export const AdjustmentAdjustStockCaller1 = (p: { input: AdjustmentAdjustment; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "warehouse_supervisor";

/** urn:corpus:inventory:receipt:operation:receive_goods — caller: caller.role = 'warehouse_staff' */
export const ReceiptReceiveGoodsCaller1 = (p: { input: ReceiptReceiveRequest; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "warehouse_staff";

/** urn:corpus:inventory:receipt:operation:receive_goods — caller: caller.role = 'purchasing_system' */
export const ReceiptReceiveGoodsCaller2 = (p: { input: ReceiptReceiveRequest; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "purchasing_system";

/** urn:corpus:inventory:reservation:operation:expire_reservation — caller: caller.role = 'clock' */
export const ReservationExpireReservationCaller1 = (p: { input: ReservationExpireRequest; current: ReservationReservation; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "clock";

/** urn:corpus:inventory:reservation:operation:expire_reservation — due: now >= current.expires_at */
export const ReservationExpireReservationDue1 = (p: { input: ReservationExpireRequest; current: ReservationReservation; now: string }): boolean =>
  Date.parse((p.now as string)) >= Date.parse((p.current.expires_at as string));

/** urn:corpus:inventory:reservation:operation:release_reservation — caller: caller.role = 'order_system' */
export const ReservationReleaseReservationCaller1 = (p: { input: ReservationReleaseRequest; current: ReservationReservation; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "order_system";

/** urn:corpus:inventory:reservation:operation:reserve_stock — ensures: input.ttl_minutes is present or output.expires_at = now + 30 minutes */
export const ReservationReserveStockEnsures1 = (p: { input: ReservationReserveRequest; now: string; output: ReservationReservation }): boolean =>
  (p.input.ttl_minutes !== undefined || Date.parse((p.output.expires_at as string)) === (Date.parse((p.now as string)) + 30 * 60000));

/** urn:corpus:inventory:reservation:operation:reserve_stock — ensures: input.ttl_minutes is absent or output.expires_at = now + input.ttl_minutes minutes */
export const ReservationReserveStockEnsures2 = (p: { input: ReservationReserveRequest; now: string; output: ReservationReservation }): boolean =>
  (p.input.ttl_minutes === undefined || Date.parse((p.output.expires_at as string)) === (Date.parse((p.now as string)) + (p.input.ttl_minutes as number) * 60000));

/** urn:corpus:inventory:reservation:operation:reserve_stock — caller: caller.role = 'order_system' */
export const ReservationReserveStockCaller1 = (p: { input: ReservationReserveRequest; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "order_system";

/** urn:corpus:inventory:reservation:operation:ship_reservation — caller: caller.role = 'order_system' */
export const ReservationShipReservationCaller1 = (p: { input: ReservationShipRequest; current: ReservationReservation; caller: AccessCaller }): boolean =>
  (p.caller?.role as string) === "order_system";
